import textwrap, pathlib
for d in ["system","constant"]: os.makedirs(d,exist_ok=True)
head = lambda cls,obj: f"""FoamFile{{version 2.0; format ascii; class {cls}; object {obj};}}\n"""

NX=NY=20; NZ=41   # 15 mm base cells
blockMeshDict = head("dictionary","blockMeshDict") + f"""
scale 1;
vertices
(
 (-0.15 -0.15 {Z_IN}) (0.15 -0.15 {Z_IN}) (0.15 0.15 {Z_IN}) (-0.15 0.15 {Z_IN})
 (-0.15 -0.15 {Z_OUT}) (0.15 -0.15 {Z_OUT}) (0.15 0.15 {Z_OUT}) (-0.15 0.15 {Z_OUT})
);
blocks ( hex (0 1 2 3 4 5 6 7) ({NX} {NY} {NZ}) simpleGrading (1 1 1) );
edges ();
boundary
(
  inlet  {{ type patch; faces ((0 3 2 1)); }}
  outlet {{ type patch; faces ((4 5 6 7)); }}
  ductWalls {{ type wall; faces ((0 1 5 4) (2 3 7 6) (1 2 6 5) (0 4 7 3)); }}
);
"""
open("system/blockMeshDict","w").write(blockMeshDict)
open("system/controlDict","w").write(head("dictionary","controlDict")+
  "application snappyHexMesh; startFrom startTime; startTime 0; stopAt endTime; endTime 1; deltaT 1; writeControl timeStep; writeInterval 1;\n")
open("system/fvSchemes","w").write(head("dictionary","fvSchemes")+"ddtSchemes{default steadyState;} gradSchemes{default Gauss linear;} divSchemes{default none;} laplacianSchemes{default Gauss linear corrected;} interpolationSchemes{default linear;} snGradSchemes{default corrected;}\n")
open("system/fvSolution","w").write(head("dictionary","fvSolution")+"solvers{} \n")
r=subprocess.run(["blockMesh"],capture_output=True,text=True); print(r.returncode, r.stdout[-500:], r.stderr[-1000:])

sfe = head("dictionary","surfaceFeatureExtractDict")+"""
barrel.stl { extractionMethod extractFromSurface; extractFromSurfaceCoeffs { includedAngle 150; } writeObj no; }
fins.stl   { extractionMethod extractFromSurface; extractFromSurfaceCoeffs { includedAngle 150; } writeObj no; }
head.stl   { extractionMethod extractFromSurface; extractFromSurfaceCoeffs { includedAngle 150; } writeObj no; }
"""
open("system/surfaceFeatureExtractDict","w").write(sfe)
r=subprocess.run(["surfaceFeatureExtract"],capture_output=True,text=True); print(r.returncode, r.stdout[-800:], r.stderr[-500:])

def write_snappy(lev_barrel, lev_fin, lev_head, lev_box, ncbl=2, nsurf=3):
    d = head("dictionary","snappyHexMeshDict")+f"""
castellatedMesh true; snap true; addLayers false;
geometry
{{
  barrel.stl {{ type triSurfaceMesh; name barrel; }}
  fins.stl   {{ type triSurfaceMesh; name fins; }}
  head.stl   {{ type triSurfaceMesh; name head; }}
  finBox {{ type searchableBox; min (-0.085 -0.085 -0.02); max (0.085 0.085 0.185); }}
}}
castellatedMeshControls
{{
  maxLocalCells 4000000; maxGlobalCells 8000000; minRefinementCells 10; maxLoadUnbalance 0.1;
  nCellsBetweenLevels {ncbl}; resolveFeatureAngle 30; allowFreeStandingZoneFaces true;
  features ( {{file "barrel.eMesh"; level {lev_barrel};}} {{file "fins.eMesh"; level {lev_fin};}} {{file "head.eMesh"; level {lev_head};}} );
  refinementSurfaces
  {{
    barrel {{ level ({lev_barrel} {lev_barrel}); patchInfo {{ type wall; }} }}
    fins   {{ level ({lev_fin} {lev_fin}); patchInfo {{ type wall; }} }}
    head   {{ level ({lev_head} {lev_head}); patchInfo {{ type wall; }} }}
  }}
  refinementRegions {{ finBox {{ mode inside; levels (( 1e15 {lev_box} )); }} }}
  locationInMesh (0.1 0.1 0.4);
}}
snapControls {{ nSmoothPatch 3; tolerance 2.0; nSolveIter 50; nRelaxIter 5; nFeatureSnapIter 10;
  implicitFeatureSnap false; explicitFeatureSnap true; multiRegionFeatureSnap false; }}
addLayersControls {{ relativeSizes true; layers{{}} expansionRatio 1.2; finalLayerThickness 0.5; minThickness 0.1;
  nGrow 0; featureAngle 60; nRelaxIter 3; nSmoothSurfaceNormals 1; nSmoothNormals 3; nSmoothThickness 10;
  maxFaceThicknessRatio 0.5; maxThicknessToMedialRatio 0.3; minMedialAxisAngle 90; nBufferCellsNoExtrude 0; nLayerIter 50; }}
meshQualityControls {{ maxNonOrtho 65; maxBoundarySkewness 20; maxInternalSkewness 4; maxConcave 80;
  minVol 1e-13; minTetQuality 1e-15; minArea -1; minTwist 0.02; minDeterminant 0.001; minFaceWeight 0.02;
  minVolRatio 0.01; minTriangleTwist -1; nSmoothScale 4; errorReduction 0.75; }}
writeFlags (); mergeTolerance 1e-6;
"""
    open("system/snappyHexMeshDict","w").write(d)

write_snappy(2,2,2,1)
r=subprocess.run(["snappyHexMesh","-overwrite"],capture_output=True,text=True)
print(r.returncode, r.stdout[-1500:], r.stderr[-500:])
